write(B/'release/candidate-binding.json',dict(candidate='D1-20261020-ENV03',scopeId=SCOPE,plan=plan,scope=plan['sha256'],authorization=authority,budget=budget,entry=entry,reference=template,captureReview=review,policy=policyPin,requests=requests,runtime=runtime,sourceFreeze=source,sourceHistory=history,authorizedRequests=2,totalPolicySlots=5,inactiveTemplates=3,productReleaseGenerated=False,productPermitGenerated=False,productSourcesChanged=0,hostBuilds=0,androidBuilds=0,productionEntryInvoked=False,sdkCalls=0,liveFilesRead=False,rootCreated=False,consumed=False,independentFinalMechanicalReview=None,D1='NOT_PASSED',M0='NOT_STARTED'))
